function depth = (n: Integer, text: String): Integer => {
let words = text.split(" ")
if n > 0 { depth(n - 1, text) + words.length } else { words.length }
}
let n = try Integer.parse(arguments.get(0) ?? "1")
console.log(depth(n, "a b"))
